# Try completing shapes into their bounding boxes (filling rectangles)
def fill_shape(grid):
    filled = [[0]*len(grid[0]) for _ in range(len(grid))]

    # Find bounding box for each non-background pixel group
    seen = set()

    for r in range(len(grid)):
        for c in range(len(grid[r])):
            color = grid[r][c]
            if color != 0 and color not in seen:
                # This pixel belongs to an object - mark it
                seen.add(color)

                # Collect all pixels of this color
                obj_pixels = []
                for tr in range(len(grid)):
                    for tc in range(len(grid[tr])):
                        if grid[tr][tc] == color:
                            obj_pixels.append((tr, tc))

                # Find bounding box
                rows = [p[0] for p in obj_pixels]
                cols = [p[1] for p in obj_pixels]
                min_r, max_r = min(rows), max(rows)
                min_c, max_c = min(cols), max(cols)

                # Fill the bounding box with this color
                for rr in range(min_r, max_r + 1):
                    for cc in range(min_c, max_c + 1):
                        filled[rr][cc] = color

    return filled

